import{_ as s,H as n,f as p,i as e}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"42 | 实战（二）：“画图”程序后端实战","description":"","frontmatter":{},"headers":[{"level":2,"title":"使用界面（接口）","slug":"使用界面-接口","link":"#使用界面-接口","children":[]},{"level":2,"title":"数据结构","slug":"数据结构","link":"#数据结构","children":[]},{"level":2,"title":"算法","slug":"算法","link":"#算法","children":[]},{"level":2,"title":"网络协议","slug":"网络协议","link":"#网络协议","children":[]},{"level":2,"title":"结语","slug":"结语","link":"#结语","children":[]}],"relativePath":"许式伟的架构课/42-实战（二）：“画图”程序后端实战.md","filePath":"许式伟的架构课/42-实战（二）：“画图”程序后端实战.md","lastUpdated":1779821983000}'),i={name:"许式伟的架构课/42-实战（二）：“画图”程序后端实战.md"};function t(l,a,r,d,c,o){return n(),p("div",null,[...a[0]||(a[0]=[e(`<h1 id="_42-实战-二-画图-程序后端实战" tabindex="-1">42 | 实战（二）：“画图”程序后端实战 <a class="header-anchor" href="#_42-实战-二-画图-程序后端实战" aria-label="Permalink to &quot;42 | 实战（二）：“画图”程序后端实战&quot;">​</a></h1><p>你好，我是七牛云许式伟。</p><p>在上一章，我们实现了一个 mock 版本的服务端，代码如下：</p><ul><li><a href="https://github.com/qiniu/qpaint/tree/v31/paintdom" target="_blank" rel="noreferrer">https://github.com/qiniu/qpaint/tree/v31/paintdom</a></li></ul><p>接下来我们将一步步迭代，把它变成一个产品级的服务端程序。</p><p>我们之前已经提到，服务端程序的业务逻辑被分为两层：底层是业务逻辑的实现层，通常我们有意识地把它组织为一颗 DOM 树。上层则是 RESTful API 层，它负责接收用户的网络请求，并转为对底层 DOM 树的方法调用。</p><p>上一讲我们关注的是 RESTful API 层。我们为了实现它，引入了 RPC 框架 <a href="https://github.com/qiniu/http" target="_blank" rel="noreferrer">restrpc</a> 和单元测试框架 <a href="https://github.com/qiniu/qiniutest" target="_blank" rel="noreferrer">qiniutest</a>。</p><p>这一讲我们关注的是底层的业务逻辑实现层。</p><h2 id="使用界面-接口" tabindex="-1">使用界面（接口） <a class="header-anchor" href="#使用界面-接口" aria-label="Permalink to &quot;使用界面（接口）&quot;">​</a></h2><p>我们先看下这一层的使用界面（接口）。从 DOM 树的角度来说，在这一讲之前，它的逻辑结构如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&amp;lt;Drawing1&amp;gt;</span></span>
<span class="line"><span>  &amp;lt;Shape11&amp;gt;</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span>  &amp;lt;Shape1M&amp;gt;</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>&amp;lt;DrawingN&amp;gt;</span></span></code></pre></div><p>从大的层次结构来说只有三层：</p><ul><li>Document =&gt; Drawing =&gt; Shape</li></ul><p>那么，在引入多租户（即多用户，每个用户有自己的 uid）之后的 DOM 树，会发生什么样的变化？</p><p>比如我们是否应该把它变成四层：</p><ul><li>Document =&gt; User =&gt; Drawing =&gt; Shape</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&amp;lt;User1&amp;gt;</span></span>
<span class="line"><span>  &amp;lt;Drawing11&amp;gt;</span></span>
<span class="line"><span>    &amp;lt;Shape111&amp;gt;</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    &amp;lt;Shape11M&amp;gt;</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span>  &amp;lt;Drawing1N&amp;gt;</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>&amp;lt;UserK&amp;gt;</span></span></code></pre></div><p>我的答案是：多租户不应该影响 DOM 树的结构。所以正确的设计应该是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&amp;lt;Drawing1&amp;gt;, 隶属于某个&amp;lt;uid&amp;gt;</span></span>
<span class="line"><span>  &amp;lt;Shape11&amp;gt;</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span>  &amp;lt;Shape1M&amp;gt;</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span>&amp;lt;DrawingN&amp;gt;, 隶属于某个&amp;lt;uid&amp;gt;</span></span></code></pre></div><p>也就是说，多租户只会导致 DOM 树多了一些额外的约定，通常我们应该把它看作某种程度的安全约定，避免访问到没有权限访问到的资源。</p><p>所以多租户不会导致 DOM 层级变化，但是它会导致接口方法的变化。比如我们看 Document 类的方法。之前，Document 类接口看起来是这样的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>func (p *Document) Add() (drawing *Drawing, err error)</span></span>
<span class="line"><span>func (p *Document) Get(dgid string) (drawing *Drawing, err error)</span></span>
<span class="line"><span>func (p *Document) Delete(dgid string) (err error)</span></span></code></pre></div><p>现在它变成了：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Add 创建新drawing。</span></span>
<span class="line"><span>func (p *Document) Add(uid UserID) (drawing *Drawing, err error)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Get 获取drawing。</span></span>
<span class="line"><span>// 我们会检查要获取的drawing是否为该uid所拥有，如果不属于则获取会失败。</span></span>
<span class="line"><span>func (p *Document) Get(uid UserID, dgid string) (drawing *Drawing, err error)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Delete 删除drawing。</span></span>
<span class="line"><span>// 我们会检查要删除的drawing是否为该uid所拥有，如果不属于删除会失败。</span></span>
<span class="line"><span>func (p *Document) Delete(uid UserID, dgid string) (err error)</span></span></code></pre></div><p>正如注释中说的那样，传入 uid 是一种约束，我们无论是获取还是删除 drawing ，都会看这个 drawing 是不是隶属于该用户。</p><p>对于 QPaint 程序来说，Document 类之外其他类的接口倒是没有发生变化。比如 Drawing 类的接口如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>func (p *Drawing) GetID() string</span></span>
<span class="line"><span>func (p *Drawing) Add(shape Shape) (err error)</span></span>
<span class="line"><span>func (p *Drawing) List() (shapes []Shape, err error)</span></span>
<span class="line"><span>func (p *Drawing) Get(id ShapeID) (shape Shape, err error)</span></span>
<span class="line"><span>func (p *Drawing) Set(id ShapeID, shape Shape) (err error)</span></span>
<span class="line"><span>func (p *Drawing) SetZorder(id ShapeID, zorder string) (err error)</span></span>
<span class="line"><span>func (p *Drawing) Delete(id ShapeID) (err error)</span></span>
<span class="line"><span>func (p *Drawing) Sync(shapes []ShapeID, changes []Shape) (err error)</span></span></code></pre></div><p>但是这只是因为 QPaint 程序的业务逻辑比较简单。虽然我们需要极力避免接口因为多租户而产生变化，但是这种影响有时候却是不可避免的。</p><p>另外，在描述类的使用界面时，我们不能只描述语言层面的约定。比如上面的 Drawing 类，我们引用图形（Shape）对象时，用的是 Go 语言的 interface。如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>type ShapeID = string</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type Shape interface {</span></span>
<span class="line"><span>    GetID() ShapeID</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>但是，是不是这一接口就是图形（Shape）的全部约束？</p><p>答案显然不是。</p><p>我们先看一个最基本的约束：考虑到 Drawing 类的 List 和 Get 返回的 Shape 实例，会被直接作为 RESTful API 的结果返回。所以，Shape 已知的一大约束是，其 json.Marshal 结果必须符合 API 层的预期。</p><p>至于在“实战二”的代码实现下，我们对 Shape 完整的约束是什么样的，欢迎你留言讨论。</p><h2 id="数据结构" tabindex="-1">数据结构 <a class="header-anchor" href="#数据结构" aria-label="Permalink to &quot;数据结构&quot;">​</a></h2><p>明确了使用界面，下一步就要考虑实现相关的内容。可能大家都听过这样一个说法：</p><blockquote><p>程序 = 数据结构 + 算法</p></blockquote><p>它是一个很好的指导思想。所以当我们谈程序的实现时，我们总是从数据结构和算法两个维度去描述它。</p><p>我们先看数据结构。</p><p>对于服务端程序，数据结构不完全是我们自己能够做主的。在 “ <a href="https://time.geekbang.org/column/article/127490" target="_blank" rel="noreferrer">36 | 业务状态与存储中间件</a>”这一讲中我们说过，存储即数据结构。所以，服务端程序在数据结构这一点上，最为重要的一件事是选择合适的存储中间件。然后我们再在该存储中间件之上组织我们的数据。</p><p>对于 QPaint 的服务端程序来说，我们选择了 mongodb。</p><p>为何是 mongodb，而不是某种关系型数据库？</p><p>最重要的理由，是因为图形（Shape）对象的开放性。因为图形的种类很多，它的 Schema 不是我们今天所能够提前预期的。故此，文档型数据库更为合适。</p><p>确定了基于 mongodb 这个存储中间件，我们下一步就是定义表结构。当然表（Table）是在关系型数据库中的说法，在 mongodb 中我们叫集合（Collection）。但是出于惯例，我们很多时候还是以 “定义表结构” 一词来表达我们想干什么。</p><p>我们定义了两个表（Collection）：drawing 和 shape。其中，drawing 表记录所有的 drawing，而 shape 表记录所有的 shape。具体如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%B8%E5%BC%8F%E4%BC%9F%E7%9A%84%E6%9E%B6%E6%9E%84%E8%AF%BE/images/136884/9ffb0216c8f979633347484bc920d35b.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%B8%E5%BC%8F%E4%BC%9F%E7%9A%84%E6%9E%B6%E6%9E%84%E8%AF%BE/images/136884/9ffb0216c8f979633347484bc920d35b.png" alt=""></a></p><p>我们重点关注索引的设计。</p><p>在 drawing 表中，我们为 uid 建立了索引。这个比较容易理解：虽然目前我们没有提供 List 某个用户所有 drawing 的方法，但这是迟早的事情。</p><p>在 shape 表中，我们为 (dgid, spid) 建立了联合唯一索引。这是因为 spid 作为 ShapeID ，是 drawing 内部唯一的，而不是全局唯一的。所以，它需要联合 dgid 作为唯一索引。</p><h2 id="算法" tabindex="-1">算法 <a class="header-anchor" href="#算法" aria-label="Permalink to &quot;算法&quot;">​</a></h2><p>谈清楚了数据结构，我们接着聊算法。</p><p>在 “程序 = 数据结构 + 算法” 这个说法中，“算法” 指的是什么？</p><p>在架构过程中，需求分析阶段，我们关注用户需求的精确表述，我们会引入角色，也就是系统的各类参与方，以及角色间的交互方式，也就是用户故事。</p><p>到了详细设计阶段，角色和用户故事就变成了子系统、模块、类或者函数的使用界面（接口）。我们前面一直在强调，使用界面（接口）应该自然体现业务需求，就是强调程序是为用户需求服务的。而我们的架构设计，在需求分析与后续的概要设计、详细设计等过程之间也有自然的延续性。</p><p>所以算法，最直白的含义，指的是用户故事背后的实现机制。</p><p>数据结构 + 算法，是为了满足最初的角色与用户故事定义，这是架构的详细设计阶段核心关注点。以下是一些典型的用户故事：</p><p><strong>创建新drawing (uid):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dgid = newObjectId()</span></span>
<span class="line"><span>db.drawing.insert({_id: dgid, uid: uid, shapes:[]})</span></span>
<span class="line"><span>return dgid</span></span></code></pre></div><p><strong>取得drawing的内容 (uid, dgid):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>doc = db.drawing.findOne({_id: dgid, uid: uid})</span></span>
<span class="line"><span>shapes = []</span></span>
<span class="line"><span>foreach spid in doc.shapes {</span></span>
<span class="line"><span>    o = db.shape.findOne({dgid: dgid, spid: spid})</span></span>
<span class="line"><span>    shapes.push(o.shape)</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>return shapes</span></span></code></pre></div><p><strong>删除drawing (uid, dgid):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if db.drawing.remove({_id: dgid, uid: uid}) { // 确保用户可删除该drawing</span></span>
<span class="line"><span>    db.shape.remove({dgid: dgid})</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>创建新shape (uid, dgid, shape):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if db.drawing.find({_id: dgid, uid: uid}) { // 确保用户可以操作该drawing</span></span>
<span class="line"><span>    db.shape.insert({dgid: dgid, spid: shape.id, shape: shape})</span></span>
<span class="line"><span>    db.drawing.update({$push: {shapes: shape.id}​})</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>删除shape (uid, dgid, spid):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if db.drawing.find({_id: dgid, uid: uid}) { // 确保用户可以操作该drawing</span></span>
<span class="line"><span>    if db.drawing.update({$pull: {shapes: spid}​}) {</span></span>
<span class="line"><span>        db.shape.remove({dgid: dgid, spid: spid})</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这些算法的表达整体是一种伪代码。但它也不完全是伪代码。如果大家用过 mongo 的 shell 的话，其实能够知道这里面的每一条 mongo 数据库操作的代码都是真实有效的。</p><p>另外，从严谨的角度来说，以上算法中凡是涉及到多次修改操作的，都应该以事务形式来做。比如删除 drawing 的代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if db.drawing.remove({_id: dgid, uid: uid}) { // 确保用户可删除该drawing</span></span>
<span class="line"><span>    db.shape.remove({dgid: dgid})</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>假如第一句 drawing 表的 remove 操作执行成功，但是在此时发生了故障停机事件导致 shape 表的 remove 没有完成，那么从用户的业务逻辑角度来说一切都正常，但是从系统维护的角度来说，系统残留了一些孤立的 shape 对象，永远都没有机会被清除。</p><h2 id="网络协议" tabindex="-1">网络协议 <a class="header-anchor" href="#网络协议" aria-label="Permalink to &quot;网络协议&quot;">​</a></h2><p>考虑到底层的业务逻辑实现层已经支持多租户，我们网络协议也需要做出相应的修改。这一讲我们只做最简单的调整，引入一个 mock 的授权机制。如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization QPaintStub &amp;lt;uid&amp;gt;</span></span></code></pre></div><p>既然有了 Authorization，那么我们就不能继续用 restrpc.Env 作为 RPC 请求的环境了。我们自己实现一个 Env，如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>type Env struct {</span></span>
<span class="line"><span>    restrpc.Env</span></span>
<span class="line"><span>    UID UserID</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>func (p *Env) OpenEnv(rcvr interface{}, w *http.ResponseWriter, req *http.Request) error {</span></span>
<span class="line"><span>    auth := req.Header.Get(&quot;Authorization&quot;)</span></span>
<span class="line"><span>    pos := strings.Index(auth, &quot; &quot;)</span></span>
<span class="line"><span>    if pos &amp;lt; 0 || auth[:pos] != &quot;QPaintStub&quot; {</span></span>
<span class="line"><span>        return errBadToken</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    uid, err := strconv.Atoi(auth[pos+1:])</span></span>
<span class="line"><span>    if err != nil {</span></span>
<span class="line"><span>        return errBadToken</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    p.UID = UserID(uid)</span></span>
<span class="line"><span>    return p.Env.OpenEnv(rcvr, w, req)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>把所有的 restrpc.Env 替换为我们自己的 Env，再对代码进行一些微调（Document 类的调用增加 env.UID 参数），我们就完成了基本的多租户改造。</p><p>改造后完整的 RESTful API 层代码如下：</p><ul><li><a href="https://github.com/qiniu/qpaint/blob/v42/paintdom/service.go" target="_blank" rel="noreferrer">https://github.com/qiniu/qpaint/blob/v42/paintdom/service.go</a></li></ul><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>总结一下今天的内容。</p><p>今天我们主要改造的是底层的业务逻辑实现层。</p><p>一方面，我们对使用界面（接口）作了多租户的改造。多租户改造从网络协议角度来说，主要是增加授权（Authorization）。从底层的 DOM 接口角度来说，主要是 Document 类增加 uid 参数。</p><p>另一方面，我们基于 mongodb 完成了新的实现。我们对数据结构和算法作了详细的描述。要更完整了解实现细节，请重点阅读以下两个文件：</p><ul><li><a href="https://github.com/qiniu/qpaint/blob/v42/paintdom/README_IMPL.md" target="_blank" rel="noreferrer">https://github.com/qiniu/qpaint/blob/v42/paintdom/README_IMPL.md</a></li><li><a href="https://github.com/qiniu/qpaint/blob/v42/paintdom/drawing.go" target="_blank" rel="noreferrer">https://github.com/qiniu/qpaint/blob/v42/paintdom/drawing.go</a></li></ul><p>如果你对今天的内容有什么思考与解读，欢迎给我留言，我们一起讨论。下一讲开始我们继续实战。</p><p>如果你觉得有所收获，也欢迎把文章分享给你的朋友。感谢你的收听，我们下期再见。</p>`,86)])])}const u=s(i,[["render",t]]);export{h as __pageData,u as default};
